    long long n;
    long long k;
    cin >> n >> k;
    vector<long long> primes(k);
    for (int i = 0; i < k; i++) cin >> primes[i];

    priority_queue<long long, vector<long long>, greater<long long>> heap;
    heap.push(1);
    long long x = 1;
    for (long long step = 0; step < n; step++) {
        x = heap.top();
        heap.pop();
        for (long long p : primes) {
            heap.push(x * p);
            if (x % p == 0) break;
        }
    }
    cout << x << "\n";

    return 0;
}

